mapper.update:
UPDATE subscription
SET next_billing_at = (CURRENT_TIMESTAMP + INTERVAL 30 DAY)
WHERE id = #{subscriptionId}

mapper.select:
SELECT status
FROM subscription
WHERE member_id = #{memberId} AND creator_id = #{creatorId}

SELECT 
FROM subscription as s
WHERE s.id = #{subscriptionId}

SELECT start_date
FROM subscription as s
WHERE s.id = #{subscriptionId}

SELECT 
FROM subscription as s
JOIN member m ON m.id = s.creator_id

    AND s.member_id = #{memberId}
    AND s.status != "REMOVED"

        AND s.id < #{cursor}


ORDER BY s.id DESC
LIMIT #{limit}
